<span class="line"><span style="color:#005CC5;">  margin-top</span><span style="color:#24292E;">: </span><span style="color:#005CC5;">calc</span><span style="color:#24292E;">(</span><span style="color:#005CC5;">var</span><span style="color:#24292E;">(</span><span style="color:#E36209;">--header-height</span><span style="color:#24292E;">) </span><span style="color:#D73A49;">*</span><span style="color:#005CC5;"> -1</span><span style="color:#24292E;">);</span></span>
